function tallestTower(n: number, caps: number[][]): number {
  let best = 0;
  for (let i = 1; i <= n; i++) {
    let h = i - 1;
    for (const [id, limit] of caps) h = Math.min(h, limit + Math.abs(i - id));
    best = Math.max(best, h);
  }
  return best;
}

