function tallestTower(n: number, caps: number[][]): number {
  const c = [[1, 0], ...caps.map(x => [x[0], x[1]])].sort((a, b) => a[0] - b[0]);
  const m = c.length;
  for (let j = 1; j < m; j++) c[j][1] = Math.min(c[j][1], c[j - 1][1] + c[j][0] - c[j - 1][0]);
  for (let j = m - 2; j >= 0; j--) c[j][1] = Math.min(c[j][1], c[j + 1][1] + c[j + 1][0] - c[j][0]);
  let best = 0;
  for (let j = 1; j < m; j++) {
    const [p1, h1] = c[j - 1], [p2, h2] = c[j];
    best = Math.max(best, Math.floor((h1 + h2 + p2 - p1) / 2));
  }
  const [pl, hl] = c[m - 1];
  return Math.max(best, hl + n - pl);
}

