        for j in range(m - 2, -1, -1):
            c[j][1] = min(c[j][1], c[j + 1][1] + c[j + 1][0] - c[j][0])
        best = 0
        for (p1, h1), (p2, h2) in zip(c, c[1:]):
            best = max(best, (h1 + h2 + p2 - p1) // 2)
        pl, hl = c[-1]
        return max(best, hl + n - pl)

